contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes an amount to deposit and drives c, then calls withdrawAll and asserts the invariant.
    function run(uint amount) public payable {
        // ensure this test contract has enough balance to deposit
        require(address(this).balance >= amount);

        // record balances before
        uint beforeThis = address(this).balance;
        uint beforeC = address(c).balance;

        // perform deposit of `amount` into c
        c.deposit{value: amount}();

        // after deposit, c's balance must have increased by amount and this decreased by amount
        uint afterDepositThis = address(this).balance;
        uint afterDepositC = address(c).balance;
        // basic sanity: balances updated as expected
        // Now attempt withdrawAll; it may revert or succeed. Capture revert via try/catch by calling from this contract.
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterWithdrawThis = address(this).balance;
        uint afterWithdrawC = address(c).balance;

        // If withdrawAll succeeded, then this contract must have received back exactly `amount` and c's balance decreased accordingly,
        // and a subsequent withdrawAll should send 0 (i.e., not change balances when it succeeds).
        if (!reverted) {
            // The net gain for this contract must equal the deposited amount
            // Use assert to express the general rule: if withdrawAll did not revert then the this-contract balance increased by amount
            // and c's balance decreased by amount, and a second withdrawAll call does not transfer additional ether.
            // We'll check second withdrawAll similarly and require it does not change balances when it succeeds.

            // perform a second withdrawAll and observe whether it reverts or not
            bool reverted2;
            uint midThis = address(this).balance;
            uint midC = address(c).balance;
            try c.withdrawAll() {
                reverted2 = false;
            } catch {
                reverted2 = true;
            }
            uint finalThis = address(this).balance;
            uint finalC = address(c).balance;

            assert(afterDepositThis + amount == afterWithdrawThis
                   && afterDepositC >= amount && afterWithdrawC + amount == afterDepositC
                   && (reverted2 || (midThis == finalThis && midC == finalC)));
        } else {
            // If it reverted, assert that balances are unchanged from after deposit (withdrawAll reverted so no transfers)
            assert(afterDepositThis == afterWithdrawThis && afterDepositC == afterWithdrawC);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function; take an amount to deposit and then attempt withdraw
    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient test balance");

        // deposit into c from this contract
        c.deposit{value: depositAmount}();

        // read observable: c's Ether balance before withdraw
        uint balBefore = address(c).balance;

        // read credit for this contract (auto-generated getter for mapping)
        uint creditBefore = c.credit(address(this));

        // attempt withdrawAll and capture whether it reverted
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint balAfter = address(c).balance;
        uint creditAfter = c.credit(address(this));

        // General rule: if withdrawAll succeeded then the caller's recorded credit is zero afterwards
        // and the contract's balance decreased by exactly the pre-withdraw credit (and if it reverted, no obligations asserted)
        assert(
            reverted
            || (creditAfter == 0 && balBefore - balAfter == creditBefore)
        );
    }

    // receive to accept Ether refunds if any
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Make a deposit then observe that both address(c).balance and the caller's credit (via withdraw behavior)
    // reflect the deposit amount. We cannot directly read credit mapping, so we check that after deposit,
    // address(c).balance has increased by amount, and a subsequent withdrawAll either reverts (in which
    // case credit must not have been consumed) or succeeds and transfers at most the deposited amount to this contract.

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // record contract balance before
        uint balBefore = address(c).balance;

        // perform the deposit of `amount` wei
        c.deposit{value: amount}();

        // record contract balance after deposit
        uint balAfter = address(c).balance;

        // attempt withdrawAll and record whether it reverted and receiver balance change
        bool reverted;
        uint selfBalBefore = address(this).balance;
        uint selfBalAfter;
        try c.withdrawAll() {
            reverted = false;
            selfBalAfter = address(this).balance;
        } catch {
            reverted = true;
            selfBalAfter = address(this).balance;
        }

        // General rule asserted:
        // 1) The contract's balance increased by exactly the deposit amount.
        // 2) If withdrawAll reverted then the caller did not receive any funds (its balance didn't increase).
        //    If withdrawAll did not revert then the caller received at most the deposited amount.
        // These are all observable through public surface: address(c).balance and address(this).balance and revert flag.
        assert(
            // balance increased by amount
            balAfter == balBefore + amount
            // and revert implies no increase to this contract's balance
            && (reverted ? (selfBalAfter == selfBalBefore)
                         // otherwise non-revert implies received <= amount
                         : (selfBalAfter >= selfBalBefore && selfBalAfter - selfBalBefore <= amount))
        );
    }

    receive() external payable {}
}
